```python
def binary_search_working(arr, target):
    left = 0
    right = len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1  # <--- Corrected line
        else:
            right = mid     # <--- Corrected line
    return -1
```

